using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class RebirthVehicleDeliveryVisualReview{
 public static void Run(){var args=Environment.GetCommandLineArgs();var p=JsonUtility.FromJson<RebirthVehicleDeliveryPipeline.Policy>(File.ReadAllText(args[Array.IndexOf(args,"-vehiclePolicy")+1]));string run=File.ReadAllText(Path.Combine(p.output,"latest-verified-run.txt")).Trim();string output=Path.Combine(run,"Renders");Directory.CreateDirectory(output);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.55f,.55f,.55f);var key=new GameObject().AddComponent<Light>();key.type=LightType.Directional;key.intensity=1.2f;key.transform.rotation=Quaternion.Euler(35,-35,0);var fill=new GameObject().AddComponent<Light>();fill.type=LightType.Directional;fill.intensity=.4f;fill.transform.rotation=Quaternion.Euler(25,150,0);var cam=new GameObject().AddComponent<Camera>();cam.orthographic=true;cam.nearClipPlane=.01f;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.12f,.14f,.16f);
 foreach(var v in p.vehicles){var bundle=AssetBundle.LoadFromFile(Path.Combine(p.output,"Bundles",v.bundle));if(!bundle)throw new Exception("Bundle missing");var root=Object.Instantiate(bundle.LoadAsset<GameObject>(v.name));try{var rs=root.GetComponentsInChildren<Renderer>(true);var bounds=rs.First().bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);foreach(string mode in new[]{"default","dye","disco"}){foreach(var r in rs)for(int i=0;i<r.sharedMaterials.Length;i++){var m=r.sharedMaterials[i];if(!m||m.shader.name!="REBIRTH/StandardVehiclePaint")continue;var b=new MaterialPropertyBlock();r.GetPropertyBlock(b,i);b.SetFloat("_PatternEnabled",mode=="disco"?1:0);b.SetColor("_Color",mode=="dye"?new Color(70,170,90,1):new Color(255,255,255,1));r.SetPropertyBlock(b,i);}float size=Mathf.Max(bounds.size.x,bounds.size.z)*.7f;cam.orthographicSize=size;cam.transform.position=bounds.center+new Vector3(-1,.55f,1).normalized*8;cam.transform.LookAt(bounds.center);var rt=new RenderTexture(1280,960,24);var t=new Texture2D(1280,960,TextureFormat.RGB24,false);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;t.ReadPixels(new Rect(0,0,1280,960),0,0);t.Apply();File.WriteAllBytes(Path.Combine(output,v.name+"-"+mode+".png"),t.EncodeToPNG());RenderTexture.active=null;cam.targetTexture=null;Object.DestroyImmediate(t);Object.DestroyImmediate(rt);}}finally{Object.DestroyImmediate(root);bundle.Unload(true);}}
 File.WriteAllText(Path.Combine(output,"receipt.txt"),"Rendered exact optimized bundles, default/dye/Disco, Unity source project lighting; no gameplay or occupant-fit proof.");}
}
